fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    // Returns true if there is any element x in `a` that also appears in `b`.
    a.iter().any(|&x| b.contains(&x))
}

fn slice_contains(s: &[i32], val: i32) -> bool {
    // Returns true if `val` appears in slice `s`.
    s.iter().any(|&x| x == val)
}

