        assert!(!slice_contains(empty, 5));

        let s = &[1, 2, 3, 4, 5];
        assert!(slice_contains(s, 1));
        assert!(slice_contains(s, 3));
        assert!(slice_contains(s, 5));
        assert!(!slice_contains(s, 0));
        assert!(!slice_contains(s, 6));
